import { Table, StringColumn, GuidColumn, BooleanColumn } from '@servicenow/sdk/core'

export const cmn_schedule = Table({
    allowWebServiceAccess: true,
    attributes: {
        kagami_csindex_enabled: true,
        update_synch: false,
    },
    display: 'name',
    extends: 'business_calendar',
    extensible: true,
    label: 'Schedule',
    name: 'cmn_schedule',
    schema: {
        document_key: StringColumn({
            label: 'Document key',
            maxLength: 32,
        }),
        document: StringColumn({
            label: 'Document',
        }),
        type: StringColumn({
            label: 'Type',
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        name: StringColumn({
            label: 'Name',
            maxLength: 80,
        }),
        read_only: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Read-only schedules cannot be modified from the user interface',
                    label: 'Read only',
                    plural: 'Read onlies',
                    language: 'en',
                },
            ],
        }),
    },
})
